INSERT INTO slp_lessons (
  id, title, description, curriculum_id, primary_skill, secondary_skill,
  domain, target, level, activity_format, topic, genially_embed_url,
  teaching_script, thumbnail_url, duration_minutes, materials, objectives,
  preparation_notes, times_used, sort_order, is_new, popularity_score, created_at
) VALUES
(1, 'WH Questions: Isolation Level Animals Adventure (Vol. 1)', 'Interactive interactive genially deck targeting receptive language and working memory through engaging animals activities designed for speech-language pathologists.', 2, 'Receptive Language', 'Working Memory', 'Language', 'WH Questions', 'Isolation', 'Interactive Genially Deck', 'Animals', 'https://view.genially.com/embed/64a1b2c3d4e5f6a7b8c9d001?lesson=1', 'Begin with warm-up cues focusing on correct tongue position and relaxed posture. Prompt the student to imitate model productions before independent attempts. Reinforce positive efforts with immediate auditory and visual feedback.', '/thumbnails/lesson-2.jpg', 15, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate WH Questions in isolation contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 691, 1, 0, 461, '2025-12-26 22:45:11'),
(2, 'Final /S/: Phrase Level Seasonal Adventure (Vol. 1)', 'Interactive teaching script targeting oral motor placement and syntax development through engaging seasonal activities designed for speech-language pathologists.', 3, 'Oral Motor Placement', 'Syntax Development', 'Articulation', 'Final /S/', 'Phrase', 'Teaching Script', 'Seasonal', NULL, 'Present the target visual stimulus and ask the student to identify the target element. Provide verbal prompts: ''Remember to use your snake sound /s/'' or ''Keep your voice smooth and continuous''. Record baseline accuracy over 10 consecutive trials.', '/thumbnails/lesson-3.jpg', 20, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Final /S/ in phrase contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 717, 2, 0, 478, '2025-12-27 05:57:11'),
(3, 'Social Problem Solving: Isolation Level Food & Cooking Adventure (Vol. 1)', 'Interactive assessment targeting social communication and expressive elaboration through engaging food & cooking activities designed for speech-language pathologists.', 6, 'Social Communication', 'Expressive Elaboration', 'Pragmatics', 'Social Problem Solving', 'Isolation', 'Assessment', 'Food & Cooking', NULL, 'Guide the student through the interactive deck step-by-step. Encourage multi-sensory awareness by having the student feel airflow or watch mouth movements in a mirror. Transition from carrier phrases to open-ended conversational retell.', '/thumbnails/lesson-4.jpg', 25, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Social Problem Solving in isolation contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 439, 3, 0, 293, '2025-12-27 13:09:11'),
(4, 'Pacing & Rate Control: Phrase Level Community Helpers Adventure (Vol. 1)', 'Interactive printable worksheet targeting self-monitoring and visual processing through engaging community helpers activities designed for speech-language pathologists.', NULL, 'Self-Monitoring', 'Visual Processing', 'Fluency', 'Pacing & Rate Control', 'Phrase', 'Printable Worksheet', 'Community Helpers', NULL, 'Introduce the minimal pair cards side-by-side to highlight meaning differences. Ask: ''Did you say sea or tea?'' Allow the student to self-correct with minimal clinician cueing before progressing to sentence-level tasks.', '/thumbnails/lesson-5.jpg', 30, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Pacing & Rate Control in phrase contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 117, 4, 0, 78, '2025-12-27 20:21:11'),
(5, 'Gliding of Liquids: Isolation Level Nature & Outdoors Adventure (Vol. 1)', 'Interactive flashcards targeting phonological awareness and semantic association through engaging nature & outdoors activities designed for speech-language pathologists.', 10, 'Phonological Awareness', 'Semantic Association', 'Phonology', 'Gliding of Liquids', 'Isolation', 'Flashcards', 'Nature & Outdoors', NULL, 'Review the conversational strategy using role-play scenarios. Prompt the student to observe the listener''s facial cues and body posture before responding. Practice maintaining the chosen topic across at least 4 conversational exchanges.', '/thumbnails/lesson-6.jpg', 10, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Gliding of Liquids in isolation contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 43, 5, 0, 29, '2025-12-28 03:33:11'),
(6, 'Plurals: Phrase Level Animals Adventure (Vol. 1)', 'Interactive interactive genially deck targeting auditory memory and fine motor control through engaging animals activities designed for speech-language pathologists.', 1, 'Auditory Memory', 'Fine Motor Control', 'Language', 'Plurals', 'Phrase', 'Interactive Genially Deck', 'Animals', 'https://view.genially.com/embed/64a1b2c3d4e5f6a7b8c9d006?lesson=6', 'Begin with warm-up cues focusing on correct tongue position and relaxed posture. Prompt the student to imitate model productions before independent attempts. Reinforce positive efforts with immediate auditory and visual feedback.', '/thumbnails/lesson-7.jpg', 15, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Plurals in phrase contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 288, 6, 0, 192, '2025-12-28 10:45:11'),
(7, 'Initial /L/: Isolation Level Seasonal Adventure (Vol. 1)', 'Interactive teaching script targeting phoneme production and self-regulation through engaging seasonal activities designed for speech-language pathologists.', 4, 'Phoneme Production', 'Self-Regulation', 'Articulation', 'Initial /L/', 'Isolation', 'Teaching Script', 'Seasonal', NULL, 'Present the target visual stimulus and ask the student to identify the target element. Provide verbal prompts: ''Remember to use your snake sound /s/'' or ''Keep your voice smooth and continuous''. Record baseline accuracy over 10 consecutive trials.', '/thumbnails/lesson-8.jpg', 20, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Initial /L/ in isolation contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 625, 7, 0, 417, '2025-12-28 17:57:11'),
(8, 'Asking Follow-Up Questions: Phrase Level Food & Cooking Adventure (Vol. 1)', 'Interactive assessment targeting theory of mind and attention to task through engaging food & cooking activities designed for speech-language pathologists.', NULL, 'Theory of Mind', 'Attention to Task', 'Pragmatics', 'Asking Follow-Up Questions', 'Phrase', 'Assessment', 'Food & Cooking', NULL, 'Guide the student through the interactive deck step-by-step. Encourage multi-sensory awareness by having the student feel airflow or watch mouth movements in a mirror. Transition from carrier phrases to open-ended conversational retell.', '/thumbnails/lesson-9.jpg', 25, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Asking Follow-Up Questions in phrase contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 745, 8, 0, 497, '2025-12-29 01:09:11'),
(9, 'Easy Onsets: Isolation Level Community Helpers Adventure (Vol. 1)', 'Interactive printable worksheet targeting fluency shaping and working memory through engaging community helpers activities designed for speech-language pathologists.', 8, 'Fluency Shaping', 'Working Memory', 'Fluency', 'Easy Onsets', 'Isolation', 'Printable Worksheet', 'Community Helpers', NULL, 'Introduce the minimal pair cards side-by-side to highlight meaning differences. Ask: ''Did you say sea or tea?'' Allow the student to self-correct with minimal clinician cueing before progressing to sentence-level tasks.', '/thumbnails/lesson-10.jpg', 30, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Easy Onsets in isolation contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 537, 9, 0, 358, '2025-12-29 08:21:11'),
(10, 'Stopping of Fricatives: Phrase Level Nature & Outdoors Adventure (Vol. 1)', 'Interactive flashcards targeting pattern elimination and syntax development through engaging nature & outdoors activities designed for speech-language pathologists.', 9, 'Pattern Elimination', 'Syntax Development', 'Phonology', 'Stopping of Fricatives', 'Phrase', 'Flashcards', 'Nature & Outdoors', NULL, 'Review the conversational strategy using role-play scenarios. Prompt the student to observe the listener''s facial cues and body posture before responding. Practice maintaining the chosen topic across at least 4 conversational exchanges.', '/thumbnails/lesson-11.jpg', 10, 'Digital interactive deck, dry-erase marker, student response tokens.', 'Student will accurately produce or demonstrate Stopping of Fricatives in phrase contexts with 80% accuracy across 3 sessions.', 'Review student baseline targets. Have visual cue cards accessible.', 193, 10, 0, 129, '2025-12-29 15:33:11'),
